  live: ["EXTENSION_UNAVAILABLE (no browser connected)", "TARGET_NOT_FOUND", "TARGET_STALE (element removed)", "SCRIPT_TIMEOUT", "DOM_MUTATION_FAILED"],
  stored: ["SESSION_NOT_FOUND", "invalid arguments"]
